# a memory store can be as simple as a table of facts
memory_store = {
    "user_123": [
        {"fact": "Prefers Python over Java", "saved_at": "2026-06-01"},
        {"fact": "Works on a backend team", "saved_at": "2026-06-03"},
    ]
}

# server exposes memory as a resource
@server.resource("memory://user/{user_id}/facts")
async def get_user_facts(user_id: str):
    facts = memory_store.get(user_id, [])
    return {
        "contents": [
            {"uri": f"memory://user/{user_id}/facts",
             "text": "\n".join(f["fact"] for f in facts)}
        ]
    }

@server.tool("remember")
async def remember(user_id: str, fact: str):
    entry = {"fact": fact, "saved_at": current_timestamp()}
    memory_store.setdefault(user_id, []).append(entry)
    return {"status": "saved", "fact": fact}

@server.tool("recall")
async def recall(user_id: str, query: str = None):
    facts = memory_store.get(user_id, [])
    if query:
        facts = [f for f in facts if query.lower() in f["fact"].lower()]
    return {"facts": [f["fact"] for f in facts]}

const memoryStore = new Map();

function remember(userId, fact) {
  const entries = memoryStore.get(userId) || [];
  entries.push({ fact, savedAt: Date.now() });
  memoryStore.set(userId, entries);
  return { status: "saved" };
}

function recall(userId) {
  return memoryStore.get(userId) || [];
}

server.tool("remember", remember);
server.tool("recall", recall);

MAX_FACTS_PER_USER = 50

def add_with_cap(user_id: str, fact: str):
    entries = memory_store.setdefault(user_id, [])
    entries.append({"fact": fact, "saved_at": current_timestamp()})
    if len(entries) > MAX_FACTS_PER_USER:
        entries.pop(0)
